CREATE TABLE payments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), customer_id uuid NOT NULL, invoice_id uuid NOT NULL, amount numeric(18,2) NOT NULL CHECK(amount>0), payment_method text NOT NULL DEFAULT '', payment_date date NOT NULL, reference_number text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY (organization_id,customer_id) REFERENCES customers(organization_id,id), FOREIGN KEY (organization_id,invoice_id) REFERENCES invoices(organization_id,id)); CREATE INDEX payments_org_customer_idx ON payments(organization_id,customer_id,payment_date DESC);
